#include <stdio.h>
#define N 10

int main(void)
{
    int a[N], i, max, count = 0;

    printf("Enter %d numbers:\n", N);
    for (i = 0; i < N; i++)
        scanf("%d", &a[i]);

    // assume first
    max = a[0];
    for (i = 1; i < N; i++) {
        // one comparison
        count++;
        if (a[i] > max)
            max = a[i];
    }

    printf("Maximum = %d\n", max);
    printf("Comparisons = %d\n", count);
    printf("Time complexity = O(n)\n");
    return 0;
}

