#include <stdio.h>

int main(void)
{
    int sizes[] = {8, 16, 32, 64};
    int k, n, i, j;
    long c1, c2, c3;

    printf("   n  O(n) O(n^2) O(logn)\n");
    for (k = 0; k < 4; k++) {
        n = sizes[k];
        c1 = c2 = c3 = 0;
        // single
        for (i = 0; i < n; i++)
            c1++;
        // nested
        for (i = 0; i < n; i++)
            for (j = 0; j < n; j++)
                c2++;
        // doubling
        for (i = 1; i < n; i = i * 2)
            c3++;
        printf("%4d %5ld %6ld %7ld\n",
               n, c1, c2, c3);
    }
    return 0;
}

