#include <stdio.h>

int main(void)
{
    long base, w, lb, lr, lc, m, n, i, j;

    printf("1-D: base w LB i: ");
    scanf("%ld %ld %ld %ld",
          &base, &w, &lb, &i);
    printf("A[%ld] = %ld\n", i,
           base + w * (i - lb));

    printf("2-D: base w LR LC M N: ");
    scanf("%ld %ld %ld %ld %ld %ld",
          &base, &w, &lr, &lc, &m, &n);
    printf("Find A[i][j], enter i j: ");
    scanf("%ld %ld", &i, &j);

    printf("Row major    = %ld\n",
           base + w*((i-lr)*n + (j-lc)));
    printf("Column major = %ld\n",
           base + w*((j-lc)*m + (i-lr)));
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a[] = {1, 2, 3, 4, 5, 6, 7};
    int n = 7, i, t;

    printf("Original: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);

    for (i = 0; i < n / 2; i++) {
        // swap ends
        t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }

    printf("\nReversed: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}

