#include <stdio.h>
#define MAX 10

int a[MAX], n = 0;

void display(void)
{
    int i;
    printf("Array: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

void insert(int pos, int item)
{
    int i;
    if (n == MAX || pos < 1 || pos > n+1) {
        printf("Invalid insert\n");
        return;
    }
    for (i = n - 1; i >= pos - 1; i--)
        a[i + 1] = a[i];
    a[pos - 1] = item;
    n++;
}

void delete(int pos)
{
    int i;
    if (pos < 1 || pos > n) {
        printf("Invalid delete\n");
        return;
    }
    for (i = pos - 1; i < n - 1; i++)
        a[i] = a[i + 1];
    n--;
}

int search(int key)
{
    int i;
    for (i = 0; i < n; i++)
        if (a[i] == key)
            return i + 1;
    return -1;
}

int main(void)
{
    int ch, pos, item;
    do {
        puts("1.Insert 2.Delete 3.Search");
        puts("4.Display 5.Exit");
        printf("Choice: ");
        scanf("%d", &ch);
        switch (ch) {
        case 1:
            printf("Position and item: ");
            scanf("%d %d", &pos, &item);
            insert(pos, item);
            break;
        case 2:
            printf("Position: ");
            scanf("%d", &pos);
            delete(pos);
            break;
        case 3:
            printf("Key: ");
            scanf("%d", &item);
            pos = search(item);
            printf("Position = %d\n", pos);
            break;
        case 4:
            display();
            break;
        }
    } while (ch != 5);
    return 0;
}
